{
  "name": "@wavelike/opencode-plugin",
  "version": "0.3.0",
  "license": "MIT",
  "description": "OpenCode plugin: sign in with your company account through Wavelike and use your organization's models.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "wavelike",
    "sso"
  ],
  "files": [
    "dist"
  ],
  "repository": {
    "type": "git",
    "url": "https://github.com/velos/wavelike.git",
    "directory": "packages/opencode-wavelike-auth"
  },
  "publishConfig": {
    "access": "public"
  },
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./package.json": "./package.json"
  },
  "dependencies": {
    "@ai-sdk/openai-compatible": "^2.0.0",
    "@openauthjs/openauth": "^0.4.3"
  },
  "peerDependencies": {
    "@opencode/plugin": "^2.2.6",
    "effect": "^4.0.0"
  }
}

import { createOpenAICompatible } from "@ai-sdk/openai-compatible";
import { Integration, Model, Plugin, Provider, } from "@opencode/plugin";
import { DEFAULT_BASE_URL, SIGN_IN_REQUIRED_MESSAGE, WAVELIKE_PROVIDER_ID, WAVELIKE_SDK_NAME, } from "./constants.js";
import { startConnectListener } from "./server.js";
import { fetchModels, modelDetails, textStacks } from "./wavelike/api.js";
import { authorizeWavelike, exchangeWavelike, pollDeviceToken, refreshWavelike, startDeviceAuthorization, } from "./wavelike/connect.js";
const providerID = Provider.ID.make(WAVELIKE_PROVIDER_ID);
const integrationID = Integration.ID.make(WAVELIKE_PROVIDER_ID);
// Force the AI SDK adapter; the bare package is rewritten to a native provider.
const sdkPackage = "aisdk:@ai-sdk/openai-compatible";
function loginForm() {
    return [
        {
            type: "string",
            key: "domain",
            title: "Company domain, such as yourcompany.com",
            ...(process.env.WAVELIKE_COMPANY_DOMAIN
                ? { default: process.env.WAVELIKE_COMPANY_DOMAIN }
                : {}),
        },
        {
            type: "string",
            key: "clientId",
            title: "Connect client ID",
            description: "Leave blank to look it up from your company domain",
            ...(process.env.WAVELIKE_CONNECT_CLIENT_ID
                ? { default: process.env.WAVELIKE_CONNECT_CLIENT_ID }
                : {}),
        },
        {
            type: "string",
            key: "baseUrl",
            title: "Wavelike API URL",
            format: "uri",
            default: DEFAULT_BASE_URL,
        },
        {
            type: "string",
            key: "profileId",
            title: "Access profile ID (optional)",
            ...(process.env.WAVELIKE_ACCESS_PROFILE_ID
                ? { default: process.env.WAVELIKE_ACCESS_PROFILE_ID }
                : {}),
        },
    ];
}
function text(answer, key) {
    return typeof answer[key] === "string" ? answer[key].trim() : "";
}
function companyDomain(answer) {
    return (text(answer, "domain") ||
        process.env.WAVELIKE_COMPANY_DOMAIN?.trim() ||
        "")
        .toLowerCase()
        .replace(/^.*@/, "");
