/**
 * Finds the sign-in client an organization chose for engineer tools from
 * its verified company domain, so engineers don't need a client ID.
 */
export async function discoverClientId(baseUrl, domain) {
    const url = new URL(`${baseUrl}/connect/discovery`);
    url.searchParams.set("domain", domain);
    const response = await fetch(url);
    const body = (await response.json().catch(() => ({})));
    if (!response.ok || typeof body.client_id !== "string") {
        throw new Error(typeof body.error_description === "string"
            ? `${body.error_description}. Ask your Wavelike admin, or enter a Connect client ID.`
            : `Couldn't find company sign-in for ${domain}. Ask your Wavelike admin, or enter a Connect client ID.`);
    }
    return body.client_id;
}
async function connectOptions(answer) {
    const baseUrl = normalizeBaseUrl(text(answer, "baseUrl") || DEFAULT_BASE_URL);
    const domain = companyDomain(answer);
    const clientId = text(answer, "clientId") ||
        process.env.WAVELIKE_CONNECT_CLIENT_ID?.trim() ||
        (domain ? await discoverClientId(baseUrl, domain) : "");
    if (!clientId) {
        throw new Error("Enter your company domain or a Connect client ID");
    }
    return {
        clientId,
        baseUrl,
        profileId: text(answer, "profileId") ||
            process.env.WAVELIKE_ACCESS_PROFILE_ID?.trim() ||
            undefined,
