    if (!["https:", "http:"].includes(url.protocol) ||
        url.username ||
        url.password ||
        url.search ||
        url.hash) {
        throw new Error("Wavelike API URL must be an HTTP(S) URL without credentials, query, or fragment");
    }
    return url.toString().replace(/\/+$/, "");
}
