        throw new Error(SIGN_IN_REQUIRED_MESSAGE);
    const { appId, baseUrl, connectClientId } = credential.metadata ?? {};
    if (typeof appId !== "string" ||
        !appId ||
        typeof baseUrl !== "string" ||
        typeof connectClientId !== "string" ||
        !connectClientId) {
        throw new Error(SIGN_IN_REQUIRED_MESSAGE);
    }
    return {
        appId,
        baseUrl: normalizeBaseUrl(baseUrl),
        connectClientId,
        credential,
