}
function toCredential(result, methodID) {
    if (result.type === "failed")
        throw new Error(result.error);
    if (!result.appId || !result.refreshToken || !result.connectClientId) {
        throw new Error("Connect response is missing app, client, or refresh token");
    }
    return {
        type: "oauth",
        methodID: Integration.MethodID.make(methodID),
        access: result.access,
        refresh: result.refreshToken,
        expires: result.expires,
        metadata: {
            appId: result.appId,
            baseUrl: result.baseUrl,
            connectClientId: result.connectClientId,
            ...(result.userId ? { userId: result.userId } : {}),
