    const url = new URL(baseUrl);
    const normalized = url.toString().replace(/\/+$/, "");
    const appPath = `/${encodeURIComponent(appId)}/v1`;
    if (url.pathname.replace(/\/+$/, "").endsWith(appPath))
        return normalized;
    return new URL(appPath, `${normalized}/`).toString().replace(/\/+$/, "");
}
async function refresh(credential) {
    const info = account(credential);
    const refreshed = toCredential(await refreshWavelike({
        refreshToken: credential.refresh,
        appId: info.appId,
        clientId: info.connectClientId,
        baseUrl: info.baseUrl,
    }), credential.methodID);
    return {
        ...refreshed,
        metadata: { ...credential.metadata, ...refreshed.metadata },
    };
}
// Serialize starts, not the whole login: a new attempt cancels the previous callback first.
function loginSlot(signal) {
    let close = async () => { };
    let starting = Promise.resolve();
    return {
        authorize(start) {
            return (answer) => {
                const result = starting.then(async () => {
                    await close();
                    signal.throwIfAborted();
                    return start(answer, (cleanup) => {
                        close = cleanup;
                    });
                });
                starting = result.then(() => { }, () => { });
                return result;
            };
        },
        async close() {
            await starting;
            await close();
        },
    };
}
function connectionKey(connection) {
    return (connection &&
        (connection.type === "credential"
            ? `credential:${connection.id}`
            : `env:${connection.name}`));
}
