    return typeof credential.metadata?.appId === "string"
        ? credential.metadata.appId
        : undefined;
}
export default Plugin.define({
    id: WAVELIKE_PROVIDER_ID,
    async setup(ctx) {
        const abort = new AbortController();
        const browserLogin = loginSlot(abort.signal);
        const deviceLogin = loginSlot(abort.signal);
        const form = loginForm();
        const reportAuthFailure = async (connection, error) => {
            if (needsSignIn(error))
                await ctx.integration.connection.status({
                    integrationID,
                    connection,
                    status: { status: "needs_auth", message: SIGN_IN_REQUIRED_MESSAGE },
                });
        };
        const resolveAccount = async (connection) => {
            try {
                const info = account(await ctx.integration.connection.resolve(connection));
                await ctx.integration.connection.status({
                    integrationID,
                    connection,
                    status: undefined,
                });
                return info;
            }
            catch (error) {
                await reportAuthFailure(connection, error);
                throw error;
            }
        };
        await ctx.integration.transform((ed) => {
            ed.update(integrationID, (integration) => {
                integration.name = "Wavelike";
            });
            ed.method.update({
                integrationID,
                method: {
                    id: "device",
                    type: "oauth",
                    label: "Wavelike Connect (device code)",
                    form,
                },
                refresh,
                label,
                authorize: deviceLogin.authorize(async (answer, own) => {
                    const auth = await startDeviceAuthorization(await connectOptions(answer));
                    if (auth.type === "failed")
                        throw new Error(auth.error);
                    const polling = new AbortController();
                    const callback = pollDeviceToken({
                        ...auth,
                        signal: polling.signal,
                    }).then((result) => toCredential(result, "device"));
                    own(async () => {
                        polling.abort();
                        await callback.catch(() => { });
                    });
                    void callback.catch(() => { });
                    return {
                        mode: "auto",
                        url: auth.verificationUriComplete,
                        instructions: `Enter code ${auth.userCode} and approve access in your browser.`,
                        expiresAt: Date.now() + auth.expiresIn * 1000,
                        callback,
                    };
                }),
            });
            ed.method.update({
                integrationID,
                method: {
                    id: "browser",
                    type: "oauth",
                    label: "Wavelike Connect (browser or paste redirect URL)",
                    form: [
                        ...form,
                        {
                            type: "string",
                            key: "organization",
                            title: "Organization slug (leave blank to use the company domain)",
                        },
                        {
                            type: "boolean",
                            key: "manual",
                            title: "Paste redirect URL only (headless)",
                            default: false,
                        },
                    ],
                },
                refresh,
                label,
                authorize: browserLogin.authorize(async (answer, own) => {
                    const organization = text(answer, "organization") || companyDomain(answer);
                    if (!organization)
                        throw new Error("Enter your company domain or organization slug");
