                    const callback = listener
                        .waitForCallback()
                        .then((url) => exchangeWavelike({
                        code: url.searchParams.get("code") ?? "",
                        state: auth.state,
                        verifier: auth.verifier,
                        appId: auth.appId,
                        clientId: auth.connectClientId,
                        baseUrl: auth.baseUrl,
                        redirectUri: auth.redirectUri,
