                        mode: "auto",
                        url: auth.url,
                        expiresAt: listener.expiresAt,
                        instructions: !listener.bound && answer.manual !== true
                            ? "The local callback couldn't start. Approve access in your browser, then paste the full redirect URL into OpenCode."
                            : "Approve access in your browser. If the browser cannot reach this server, paste the full redirect URL into OpenCode.",
                        callback,
                        submit: listener.submit,
