        await ctx.provider.transform((ed) => {
            ed.add({
                info: {
                    id: providerID,
                    name: "Wavelike",
                    package: sdkPackage,
                    integrationID,
                    activation: "auto",
                    settings: { baseURL: inventory.baseURL ?? DEFAULT_BASE_URL },
                },
                models: inventory.models,
                sourceConnection: inventory.connection,
