        });
        await ctx.aisdk.hook("sdk", async (hook) => {
            const connection = await ctx.integration.connection.active(integrationID);
            if (!connection)
                throw new Error(SIGN_IN_REQUIRED_MESSAGE);
            const info = await resolveAccount(connection);
            const baseURL = buildAppBaseUrl(info.baseUrl, info.appId);
            hook.options.baseURL = baseURL;
