                        connection,
                        baseURL,
                        models: textStacks(list.data).map((model) => {
                            const details = modelDetails(model);
                            return {
                                ...Model.Info.default(providerID, Model.ID.make(model.id)),
                                name: details.name,
                                capabilities: {
                                    tools: true,
                                    temperature: true,
                                    input: details.imageInput ? ["text", "image"] : ["text"],
                                    output: ["text"],
                                },
                                // The stack's own limits, so OpenCode compacts in time.
                                limit: { context: details.context, output: details.output },
