import { createServer } from "node:http";
export async function startConnectListener({ redirectUri, state, manual = false, timeoutMs = 5 * 60 * 1000, }) {
    const redirect = new URL(redirectUri);
    let settled = false;
    let resolveCallback;
    let rejectCallback;
    const callback = new Promise((resolve, reject) => {
        resolveCallback = resolve;
        rejectCallback = reject;
    });
    // A timeout/cleanup can happen before the host attaches its callback handler.
    void callback.catch(() => { });
    const expiresAt = Date.now() + timeoutMs;
    const timeout = setTimeout(() => {
        if (settled)
            return;
        settled = true;
        rejectCallback(new Error("Timed out waiting for Connect callback"));
        server.close();
        server.closeAllConnections();
    }, timeoutMs);
    timeout.unref();
    const submit = async (input) => {
        if (settled)
            throw new Error("Connect authorization has already completed or expired");
        const url = new URL(input.trim());
        if (url.origin !== redirect.origin || url.pathname !== redirect.pathname)
            throw new Error("Unexpected Connect redirect URL");
        if (url.searchParams.get("state") !== state)
            throw new Error("Connect state mismatch");
        const error = url.searchParams.get("error");
        if (!error && !url.searchParams.get("code"))
            throw new Error("Missing code in Connect redirect URL");
        settled = true;
        clearTimeout(timeout);
        if (error)
            rejectCallback(new Error(`Connect authorization failed: ${error}`));
        else
            resolveCallback(url);
        server.close();
    };
    const server = createServer((request, response) => {
        void submit(new URL(request.url ?? "/", redirect.origin).toString()).then(() => {
            response.writeHead(200, { "Content-Type": "text/plain" });
            response.end("Return to OpenCode to finish authentication.");
        }, (error) => {
            response.writeHead(400, { "Content-Type": "text/plain" });
            response.end(error instanceof Error ? error.message : "Invalid Connect callback");
        });
    });
    let bound = false;
    if (!manual) {
        // Binding failure leaves the same validated paste path available to headless clients.
        await new Promise((resolve) => {
            const failed = () => resolve();
            server.once("error", failed);
            server.listen(Number(redirect.port || 80), "127.0.0.1", () => {
                bound = true;
                server.off("error", failed);
                resolve();
            });
        });
    }
    return {
        expiresAt,
        bound,
        waitForCallback: () => callback,
        submit,
        close: async () => {
            clearTimeout(timeout);
            if (!settled) {
                settled = true;
                rejectCallback(new Error("Connect authorization cancelled"));
            }
            await new Promise((resolve) => {
                server.close(() => resolve());
                server.closeAllConnections();
            });
        },
    };
}
